import{_ as p,a0 as o,w as d,s as r,I as s,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 終端管理你的日曆 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 終端管理你的日曆 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 終端管理你的日曆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 終端管理你的日曆 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command","title":"在 Linux 終端管理你的日曆","tag":"202204","desc":""},"relativePath":"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command.md","filePath":"[post].md"}'),u={name:"202204/20220215 Manage your calendar from the Linux terminal with the konsolekalendar command.md"};function k(m,a,g,c,h,f){const e=o("Link");return d(),r("div",null,[a[27]||(a[27]=s("h1",{id:"在-linux-終端管理你的日曆",tabindex:"-1"},[n("在 Linux 終端管理你的日曆 "),s("a",{class:"header-anchor",href:"#在-linux-終端管理你的日曆","aria-label":"Permalink to “在 Linux 終端管理你的日曆”"},"​")],-1)),a[28]||(a[28]=s("blockquote",null,[s("p",null,"KDE 很適合在 Linux 上進行基於終端的日程安排。konsolekalendar 命令讓你從終端查看和管理 iCal 日曆。")],-1)),a[29]||(a[29]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/18/161418rsp7x2evo6zl766v.jpg",alt:""})],-1)),s("p",null,[a[1]||(a[1]=n("我是一個 ",-1)),l(e,{href:"https://opensource.com/article/17/5/7-cool-kde-tweaks-will-improve-your-life"},{default:i(()=>[...a[0]||(a[0]=[n("KDE 用户",-1)])]),_:1}),a[2]||(a[2]=n("，多年來我一直在 Plasma 桌面上進行着看似無盡的探索。如果你在公開場合問我，我可能會聲稱自己對我每天使用的桌面瞭如指掌。但實際上，我只是剛剛觸及到表面而已。似乎每天我都能學到一個新的 KDE 技巧，讓我的生活變得更輕鬆或更有趣，我最新的發現是 ",-1)),a[3]||(a[3]=s("code",null,"konsolekalendar",-1)),a[4]||(a[4]=n(" 命令，它讓你從終端查看和管理 iCal 日曆。",-1))]),a[30]||(a[30]=t('<h3 id="akonadi" tabindex="-1">Akonadi <a class="header-anchor" href="#akonadi" aria-label="Permalink to “Akonadi”">​</a></h3><p>Akonadi 項目是一個底層 KDE 框架，幫助 Plasma 桌面跟蹤所有的個人信息管理器（PIM）數據。它主要是為開發者服務的，包括很多可以讓程序員用來創建應用的庫，通過這些程序你可以訪問你的聯繫人、筆記、電子郵件、日曆等等。Akonadi 中包括一些終端命令，比如 <code>akonadictl</code> 可以啓動和停止 Akonadi 服務，但它們大多是為了排除故障。然而，<code>konsolekalendar</code> 是一個面向用户的命令，可以讓你完全訪問 Kontact 套件的所有數據，包括 KMail、Notes 和日曆。</p><p>如果你正在運行 KDE 的 Plasma 桌面，那麼你已經安裝了 Kontact 套件。</p><p><img src="https://opensource.com/sites/default/files/uploads/kontact.jpg" alt="Kontact UI" title="Kontact UI"></p><p>你也安裝好了 Akonadi 和它的工具，所以你所需要的基於終端的日曆完成了!</p><h3 id="從終端查看你的日曆" tabindex="-1">從終端查看你的日曆 <a class="header-anchor" href="#從終端查看你的日曆" aria-label="Permalink to “從終端查看你的日曆”">​</a></h3>',6)),s("p",null,[a[7]||(a[7]=n("由於 ",-1)),l(e,{href:"https://opensource.com/article/21/1/nextcloud-productivity"},{default:i(()=>[...a[5]||(a[5]=[n("NextCloud",-1)])]),_:1}),a[8]||(a[8]=n(" 和 ",-1)),l(e,{href:"https://radicale.org/v3.html"},{default:i(()=>[...a[6]||(a[6]=[n("Radicale",-1)])]),_:1}),a[9]||(a[9]=n(" 等項目的存在，你可以託管自己的 iCal 日曆服務，或者你可能已經在流行的供應商（例如，Google）那裏擁有一個 iCal 賬户。當你使用 Kontact 管理日曆時，你訂閲了一個日曆對象（用 Akonadi 的術語説是一個“",-1)),a[10]||(a[10]=s("ruby",null,[n("集合"),s("rt",null,"collection")],-1)),a[11]||(a[11]=n("”）。當你對你的本地日曆進行更新時，這些變化會被送回你的 iCal 服務器以同步你的日曆服務器和客户端。",-1))]),a[31]||(a[31]=t(`<p>無論你是否使用過 Kontact 的日曆功能，你在 Kontact 中都有一些默認的日曆對象。你有一個叫<strong>個人日曆</strong>和<strong>生日和紀念日</strong>的日曆對象。</p><p>以下是如何顯示當天的日曆（默認為<strong>個人日曆</strong>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        10:00 AM - 11:00 AM</span></span>
<span class="line"><span>Summary: Covid booster shot</span></span>
<span class="line"><span>UID: 8d8a1e38-c88c-4d84-99e5-23...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        12:00 PM - 01:00 PM</span></span>
<span class="line"><span>Summary: Lunch</span></span>
<span class="line"><span>UID: 7aa89a...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        01:00 PM - 04:45 PM</span></span>
<span class="line"><span>Summary: Afternoon coding</span></span>
<span class="line"><span>UID: 9cde38b...</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        06:00 PM - 10:00 PM</span></span>
<span class="line"><span>Summary: Planescape game</span></span>
<span class="line"><span>UID: c73f7e98-722f-48a2-8006-66...</span></span>
<span class="line"><span>----------------------------------</span></span></code></pre></div><h3 id="添加一個事件" tabindex="-1">添加一個事件 <a class="header-anchor" href="#添加一個事件" aria-label="Permalink to “添加一個事件”">​</a></h3><p>要查看你訂閲的所有日曆，請使用 <code>--list-calendars</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --list-calendars</span></span>
<span class="line"><span>----------------------------------</span></span>
<span class="line"><span>3  - (Read only) Birthdays &amp; Anniversaries</span></span>
<span class="line"><span>11 - Personal Calendar</span></span>
<span class="line"><span>60 - (Read only) Open Invitations</span></span>
<span class="line"><span>61 - (Read only) Declined Invitations</span></span>
<span class="line"><span>66 - Dnd</span></span>
<span class="line"><span>67 - Work</span></span>
<span class="line"><span>68 - Museum</span></span></code></pre></div><p>左邊的數字是日曆的 ID。要添加一個事件到一個特定的日曆，請使用 <code>--calendar</code> 選項，然後是日曆 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --add --calendar 66 \\</span></span>
<span class="line"><span>--date 2022-01-16 \\</span></span>
<span class="line"><span>--time 20:00 --end-time 23:59 \\</span></span>
<span class="line"><span>--summary &quot;Another game&quot; \\</span></span>
<span class="line"><span>--description &quot;Remember to bring dice&quot; \\</span></span>
<span class="line"><span>Success: &quot;Another game&quot; inserted</span></span></code></pre></div><h3 id="刪除一個事件" tabindex="-1">刪除一個事件 <a class="header-anchor" href="#刪除一個事件" aria-label="Permalink to “刪除一個事件”">​</a></h3><p>你也可以刪除事件。每個事件都有一個唯一的 ID（UID），在每個事件列表的底部提供：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --list</span></span>
<span class="line"><span>Date:   Saturday, January 15, 2022</span></span>
<span class="line"><span>        06:00 PM - 10:00 PM</span></span>
<span class="line"><span>Summary: Planescape game</span></span>
<span class="line"><span>UID: c73f7e98-722f-48a2-8006-66aa8ddcf789</span></span></code></pre></div><p>要刪除一個事件，請使用 <code>--delete</code> 選項，同時使用 <code>--uid</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ konsolekalendar --delete \\</span></span>
<span class="line"><span>--uid c73f7e98-722f-48a2-8006-66aa8ddcf789</span></span></code></pre></div><h3 id="終端中的-akonadi" tabindex="-1">終端中的 Akonadi <a class="header-anchor" href="#終端中的-akonadi" aria-label="Permalink to “終端中的 Akonadi”">​</a></h3><p>你用 <code>konsolekalendar</code> 所做的一切都會立即在 Akonadi 中執行，並在 Kontact 中得到同樣快的反映。使用一個並不意味着你必須放棄另一個。由於它們共享 Akonadi 後端，兩者查看和編輯相同的數據。<code>konsolekalendar</code> 命令是一項正在進行的工作。未來的計劃包括與 Kontact 的筆記和日記部分的整合，而且還有很多比本文所涉及的更多的選項。如果你在使用 KDE 桌面，試試 <code>konsolekalendar</code>，體驗一下終端的 PIM！</p><hr>`,16)),s("p",null,[a[13]||(a[13]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/22/2/manage-calendar-linux-konsolekalender-kde"},{default:i(()=>[...a[12]||(a[12]=[n("https://opensource.com/article/22/2/manage-calendar-linux-konsolekalender-kde",-1)])]),_:1})]),s("p",null,[a[18]||(a[18]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...a[14]||(a[14]=[n("Seth Kenlon",-1)])]),_:1}),a[19]||(a[19]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[15]||(a[15]=[n("lujun9972",-1)])]),_:1}),a[20]||(a[20]=n(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[16]||(a[16]=[n("geekpi",-1)])]),_:1}),a[21]||(a[21]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[17]||(a[17]=[n("wxy",-1)])]),_:1})]),s("p",null,[a[24]||(a[24]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[22]||(a[22]=[n("LCTT",-1)])]),_:1}),a[25]||(a[25]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...a[23]||(a[23]=[n("Linux中國",-1)])]),_:1}),a[26]||(a[26]=n(" 榮譽推出",-1))])])}const C=p(u,[["render",k]]);export{y as __pageData,C as default};
